import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------- CUDA kernel source -------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void tanh_kernel(const scalar_t* __restrict__ input,
                            scalar_t* __restrict__ output,
                            const int64_t N) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = blockDim.x * gridDim.x;
    for (int64_t i = idx; i < N; i += stride) {
        // Convert half to float, compute tanh, convert back
        float val = __half2float(input[i]);
        float tanh_val = tanhf(val);
        output[i] = __float2half(tanh_val);
    }
}

// Entry point called from Python
torch::Tensor tanh_fp16_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    auto output = torch::empty_like(input);
    const int64_t N = input.numel();

    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "tanh_fp16_cuda", ([&] {
        tanh_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            N);
    }));

    // Ensure kernel launch errors are caught
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel failed: ") + cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("tanh_fp16_cuda", &tanh_fp16_cuda, "Half-precision Tanh (CUDA)");
}
'''

# ------------------- Compile the extension -------------------
tanh_module = load_inline(name='tanh_fp16_ext',
                          cpp_sources='',
                          cuda_sources=cuda_source,
                          functions=['tanh_fp16_cuda'],
                          verbose=False)

# ------------------- Model definition -------------------
class ModelNew(nn.Module):
    """
    Model that applies a half‑precision Tanh using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Tanh activation to the input tensor using the custom kernel.

        Args:
            x (torch.Tensor): Input tensor of any shape, dtype torch.float16, on CUDA.

        Returns:
            torch.Tensor: Output tensor with Tanh applied, same shape and dtype as input.
        """
        if not x.is_cuda:
            raise RuntimeError("ModelNew expects input tensor on CUDA")
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew expects input tensor of dtype torch.float16")
        return tanh_module.tanh_fp16_cuda(x)

# ------------------- Helper functions matching reference API -------------------
def get_inputs():
    # Generate fp16 inputs on CUDA to match the kernel expectations
